BEGIN;
SET LOCAL app.local_heroes_disposable='local-heroes-phase02-disposable';
SET standard_conforming_strings=on;
CREATE TEMP TABLE lh_expected(table_name text NOT NULL,row_data jsonb NOT NULL) ON COMMIT DROP;
CREATE FUNCTION pg_temp.lh_import_drafts() RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER AS $lh_import$
BEGIN
  IF current_setting('app.local_heroes_disposable',true) IS DISTINCT FROM 'local-heroes-phase02-disposable' OR current_database()<>'postgres' THEN RAISE EXCEPTION 'DISPOSABLE_TARGET_REQUIRED'; END IF;
  PERFORM pg_advisory_xact_lock(18012,3401);
  IF (SELECT count(*) FROM public.history_localities)<>34 THEN RAISE EXCEPTION 'REGISTRY_MISMATCH'; END IF;
  IF EXISTS(SELECT 1 FROM public.historical_figures actual JOIN lh_expected e ON e.table_name='historical_figures' AND (public.local_hero_fold(actual.name)=public.local_hero_fold(e.row_data->>'name') OR actual.slug=e.row_data->>'slug') WHERE actual.id<>(e.row_data->>'id')::uuid)
    OR EXISTS(SELECT 1 FROM public.event_figures actual JOIN lh_expected e ON e.table_name='historical_figures' AND actual.figure_id=(e.row_data->>'id')::uuid) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='LEGACY_IDENTITY_CONFLICT'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.sources,e.row_data) expected INNER JOIN public.sources actual ON actual.id=expected.id WHERE e.table_name='sources' AND (ROW(actual.id,actual.title,actual.author_org,actual.publisher,actual.published_year,actual.url,actual.source_type,actual.citation,actual.accessed_at) IS DISTINCT FROM ROW(expected.id,expected.title,expected.author_org,expected.publisher,expected.published_year,expected.url,expected.source_type,expected.citation,expected.accessed_at))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:sources'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.historical_figures,e.row_data) expected INNER JOIN public.historical_figures actual ON actual.id=expected.id WHERE e.table_name='historical_figures' AND (ROW(actual.id,actual.name,actual.slug,actual.other_names,actual.birth_year,actual.death_year,actual.biography,actual.portrait_url,actual.workflow_status,actual.review_note,actual.is_local_hero,actual.contribution_summary,actual.contribution_start_year,actual.contribution_end_year,actual.catalog_aliases) IS DISTINCT FROM ROW(expected.id,expected.name,expected.slug,expected.other_names,expected.birth_year,expected.death_year,expected.biography,expected.portrait_url,expected.workflow_status,expected.review_note,expected.is_local_hero,expected.contribution_summary,expected.contribution_start_year,expected.contribution_end_year,expected.catalog_aliases))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:historical_figures'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_sources,e.row_data) expected INNER JOIN public.figure_sources actual ON actual.figure_id=expected.figure_id AND actual.claim_key=expected.claim_key AND actual.source_id=expected.source_id WHERE e.table_name='figure_sources' AND (ROW(actual.figure_id,actual.claim_key,actual.source_id,actual.claim_text,actual.locator,actual.scope_note,actual.certainty,actual.uncertainty_note) IS DISTINCT FROM ROW(expected.figure_id,expected.claim_key,expected.source_id,expected.claim_text,expected.locator,expected.scope_note,expected.certainty,expected.uncertainty_note))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_sources'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_stories,e.row_data) expected INNER JOIN public.figure_stories actual ON actual.id=expected.id WHERE e.table_name='figure_stories' AND (ROW(actual.id,actual.figure_id,actual.slug,actual.title,actual.summary,actual.body,actual.sort_order,actual.is_primary,actual.workflow_status,actual.review_note) IS DISTINCT FROM ROW(expected.id,expected.figure_id,expected.slug,expected.title,expected.summary,expected.body,expected.sort_order,expected.is_primary,expected.workflow_status,expected.review_note))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_stories'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_story_sources,e.row_data) expected INNER JOIN public.figure_story_sources actual ON actual.story_id=expected.story_id AND actual.claim_key=expected.claim_key AND actual.source_id=expected.source_id WHERE e.table_name='figure_story_sources' AND (ROW(actual.story_id,actual.claim_key,actual.source_id,actual.claim_text,actual.locator,actual.scope_note,actual.certainty,actual.uncertainty_note) IS DISTINCT FROM ROW(expected.story_id,expected.claim_key,expected.source_id,expected.claim_text,expected.locator,expected.scope_note,expected.certainty,expected.uncertainty_note))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_story_sources'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_localities,e.row_data) expected INNER JOIN public.figure_localities actual ON actual.id=expected.id WHERE e.table_name='figure_localities' AND (ROW(actual.id,actual.figure_id,actual.locality_code,actual.relationship_kind,actual.historical_place_label,actual.explanation,actual.claim_key,actual.primary_source_id,actual.certainty,actual.uncertainty_note) IS DISTINCT FROM ROW(expected.id,expected.figure_id,expected.locality_code,expected.relationship_kind,expected.historical_place_label,expected.explanation,expected.claim_key,expected.primary_source_id,expected.certainty,expected.uncertainty_note))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_localities'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.media_assets,e.row_data) expected INNER JOIN public.media_assets actual ON actual.id=expected.id WHERE e.table_name='media_assets' AND (ROW(actual.id,actual.figure_id,actual.event_id,actual.location_id,actual.file_url,actual.media_type,actual.caption,actual.alt_text,actual.source_id,actual.sort_order,actual.era,actual.year_taken,actual.is_reenactment,actual.is_colorized,actual.is_cover,actual.photographer,actual.license,actual.license_url,actual.source_page_url,actual.width,actual.height,actual.focal_point) IS DISTINCT FROM ROW(expected.id,expected.figure_id,expected.event_id,expected.location_id,expected.file_url,expected.media_type,expected.caption,expected.alt_text,expected.source_id,expected.sort_order,expected.era,expected.year_taken,expected.is_reenactment,expected.is_colorized,expected.is_cover,expected.photographer,expected.license,expected.license_url,expected.source_page_url,expected.width,expected.height,expected.focal_point))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:media_assets'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_media_evidence,e.row_data) expected INNER JOIN public.figure_media_evidence actual ON actual.media_id=expected.media_id WHERE e.table_name='figure_media_evidence' AND (ROW(actual.media_id,actual.figure_id,actual.depiction_kind,actual.decision,actual.identity_source_id,actual.identity_locator,actual.identity_certainty,actual.usage_basis,actual.usage_source_id,actual.usage_locator,actual.usage_note,actual.checked_at) IS DISTINCT FROM ROW(expected.media_id,expected.figure_id,expected.depiction_kind,expected.decision,expected.identity_source_id,expected.identity_locator,expected.identity_certainty,expected.usage_basis,expected.usage_source_id,expected.usage_locator,expected.usage_note,expected.checked_at))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_media_evidence'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.sources,e.row_data) expected LEFT JOIN public.sources actual ON actual.id=expected.id WHERE e.table_name='sources' AND (actual.id IS NULL OR ROW(actual.id,actual.title,actual.author_org,actual.publisher,actual.published_year,actual.url,actual.source_type,actual.citation,actual.accessed_at) IS DISTINCT FROM ROW(expected.id,expected.title,expected.author_org,expected.publisher,expected.published_year,expected.url,expected.source_type,expected.citation,expected.accessed_at))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:sources'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.historical_figures,e.row_data) expected LEFT JOIN public.historical_figures actual ON actual.id=expected.id WHERE e.table_name='historical_figures' AND (actual.id IS NULL OR ROW(actual.id,actual.name,actual.slug,actual.other_names,actual.birth_year,actual.death_year,actual.biography,actual.portrait_url,actual.workflow_status,actual.review_note,actual.is_local_hero,actual.contribution_summary,actual.contribution_start_year,actual.contribution_end_year,actual.catalog_aliases) IS DISTINCT FROM ROW(expected.id,expected.name,expected.slug,expected.other_names,expected.birth_year,expected.death_year,expected.biography,expected.portrait_url,expected.workflow_status,expected.review_note,expected.is_local_hero,expected.contribution_summary,expected.contribution_start_year,expected.contribution_end_year,expected.catalog_aliases))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:historical_figures'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_sources,e.row_data) expected LEFT JOIN public.figure_sources actual ON actual.figure_id=expected.figure_id AND actual.claim_key=expected.claim_key AND actual.source_id=expected.source_id WHERE e.table_name='figure_sources' AND (actual.figure_id IS NULL OR ROW(actual.figure_id,actual.claim_key,actual.source_id,actual.claim_text,actual.locator,actual.scope_note,actual.certainty,actual.uncertainty_note) IS DISTINCT FROM ROW(expected.figure_id,expected.claim_key,expected.source_id,expected.claim_text,expected.locator,expected.scope_note,expected.certainty,expected.uncertainty_note))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_sources'; END IF;
  IF EXISTS(SELECT 1 FROM public.figure_sources actual WHERE actual.figure_id IN (SELECT (row_data->>'id')::uuid FROM lh_expected WHERE table_name='historical_figures') AND NOT EXISTS(SELECT 1 FROM lh_expected e WHERE e.table_name='figure_sources' AND to_jsonb(actual)->'figure_id'=e.row_data->'figure_id' AND to_jsonb(actual)->'claim_key'=e.row_data->'claim_key' AND to_jsonb(actual)->'source_id'=e.row_data->'source_id')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='UNEXPECTED_GRAPH_LINK:figure_sources'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_stories,e.row_data) expected LEFT JOIN public.figure_stories actual ON actual.id=expected.id WHERE e.table_name='figure_stories' AND (actual.id IS NULL OR ROW(actual.id,actual.figure_id,actual.slug,actual.title,actual.summary,actual.body,actual.sort_order,actual.is_primary,actual.workflow_status,actual.review_note) IS DISTINCT FROM ROW(expected.id,expected.figure_id,expected.slug,expected.title,expected.summary,expected.body,expected.sort_order,expected.is_primary,expected.workflow_status,expected.review_note))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_stories'; END IF;
  IF EXISTS(SELECT 1 FROM public.figure_stories actual WHERE actual.figure_id IN (SELECT (row_data->>'id')::uuid FROM lh_expected WHERE table_name='historical_figures') AND NOT EXISTS(SELECT 1 FROM lh_expected e WHERE e.table_name='figure_stories' AND to_jsonb(actual)->'id'=e.row_data->'id')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='UNEXPECTED_GRAPH_LINK:figure_stories'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_story_sources,e.row_data) expected LEFT JOIN public.figure_story_sources actual ON actual.story_id=expected.story_id AND actual.claim_key=expected.claim_key AND actual.source_id=expected.source_id WHERE e.table_name='figure_story_sources' AND (actual.story_id IS NULL OR ROW(actual.story_id,actual.claim_key,actual.source_id,actual.claim_text,actual.locator,actual.scope_note,actual.certainty,actual.uncertainty_note) IS DISTINCT FROM ROW(expected.story_id,expected.claim_key,expected.source_id,expected.claim_text,expected.locator,expected.scope_note,expected.certainty,expected.uncertainty_note))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_story_sources'; END IF;
  IF EXISTS(SELECT 1 FROM public.figure_story_sources actual WHERE actual.story_id IN (SELECT (row_data->>'id')::uuid FROM lh_expected WHERE table_name='figure_stories') AND NOT EXISTS(SELECT 1 FROM lh_expected e WHERE e.table_name='figure_story_sources' AND to_jsonb(actual)->'story_id'=e.row_data->'story_id' AND to_jsonb(actual)->'claim_key'=e.row_data->'claim_key' AND to_jsonb(actual)->'source_id'=e.row_data->'source_id')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='UNEXPECTED_GRAPH_LINK:figure_story_sources'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_localities,e.row_data) expected LEFT JOIN public.figure_localities actual ON actual.id=expected.id WHERE e.table_name='figure_localities' AND (actual.id IS NULL OR ROW(actual.id,actual.figure_id,actual.locality_code,actual.relationship_kind,actual.historical_place_label,actual.explanation,actual.claim_key,actual.primary_source_id,actual.certainty,actual.uncertainty_note) IS DISTINCT FROM ROW(expected.id,expected.figure_id,expected.locality_code,expected.relationship_kind,expected.historical_place_label,expected.explanation,expected.claim_key,expected.primary_source_id,expected.certainty,expected.uncertainty_note))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_localities'; END IF;
  IF EXISTS(SELECT 1 FROM public.figure_localities actual WHERE actual.figure_id IN (SELECT (row_data->>'id')::uuid FROM lh_expected WHERE table_name='historical_figures') AND NOT EXISTS(SELECT 1 FROM lh_expected e WHERE e.table_name='figure_localities' AND to_jsonb(actual)->'id'=e.row_data->'id')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='UNEXPECTED_GRAPH_LINK:figure_localities'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.media_assets,e.row_data) expected LEFT JOIN public.media_assets actual ON actual.id=expected.id WHERE e.table_name='media_assets' AND (actual.id IS NULL OR ROW(actual.id,actual.figure_id,actual.event_id,actual.location_id,actual.file_url,actual.media_type,actual.caption,actual.alt_text,actual.source_id,actual.sort_order,actual.era,actual.year_taken,actual.is_reenactment,actual.is_colorized,actual.is_cover,actual.photographer,actual.license,actual.license_url,actual.source_page_url,actual.width,actual.height,actual.focal_point) IS DISTINCT FROM ROW(expected.id,expected.figure_id,expected.event_id,expected.location_id,expected.file_url,expected.media_type,expected.caption,expected.alt_text,expected.source_id,expected.sort_order,expected.era,expected.year_taken,expected.is_reenactment,expected.is_colorized,expected.is_cover,expected.photographer,expected.license,expected.license_url,expected.source_page_url,expected.width,expected.height,expected.focal_point))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:media_assets'; END IF;
  IF EXISTS(SELECT 1 FROM public.media_assets actual WHERE actual.figure_id IN (SELECT (row_data->>'id')::uuid FROM lh_expected WHERE table_name='historical_figures') AND NOT EXISTS(SELECT 1 FROM lh_expected e WHERE e.table_name='media_assets' AND to_jsonb(actual)->'id'=e.row_data->'id')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='UNEXPECTED_GRAPH_LINK:media_assets'; END IF;
  IF EXISTS(SELECT 1 FROM lh_expected e CROSS JOIN LATERAL jsonb_populate_record(NULL::public.figure_media_evidence,e.row_data) expected LEFT JOIN public.figure_media_evidence actual ON actual.media_id=expected.media_id WHERE e.table_name='figure_media_evidence' AND (actual.media_id IS NULL OR ROW(actual.media_id,actual.figure_id,actual.depiction_kind,actual.decision,actual.identity_source_id,actual.identity_locator,actual.identity_certainty,actual.usage_basis,actual.usage_source_id,actual.usage_locator,actual.usage_note,actual.checked_at) IS DISTINCT FROM ROW(expected.media_id,expected.figure_id,expected.depiction_kind,expected.decision,expected.identity_source_id,expected.identity_locator,expected.identity_certainty,expected.usage_basis,expected.usage_source_id,expected.usage_locator,expected.usage_note,expected.checked_at))) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IDENTITY_OR_CONTENT_CONFLICT:figure_media_evidence'; END IF;
  IF EXISTS(SELECT 1 FROM public.figure_media_evidence actual WHERE actual.figure_id IN (SELECT (row_data->>'id')::uuid FROM lh_expected WHERE table_name='historical_figures') AND NOT EXISTS(SELECT 1 FROM lh_expected e WHERE e.table_name='figure_media_evidence' AND to_jsonb(actual)->'media_id'=e.row_data->'media_id')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='UNEXPECTED_GRAPH_LINK:figure_media_evidence'; END IF;
  SET CONSTRAINTS ALL IMMEDIATE;
  SET CONSTRAINTS ALL DEFERRED;
  RETURN jsonb_build_object('snapshotHash','4110c2782371654e0f74621036fb680b995aebe1c1ba1795dddd67ed0d43cbc8','draftPeople',35,'reviewedGraphs',2,'nationalReleaseReady',false);
END $lh_import$;
SELECT pg_temp.lh_import_drafts();
-- Explicitly disposable, uncommitted promotion; never a national release.
SET LOCAL ROLE authenticated;
DO $lh_promote$ DECLARE outcome jsonb; BEGIN
  PERFORM set_config('request.jwt.claim.sub','a7070000-0000-4000-8000-000000000001',true);
    outcome:=public.local_hero_submit_graph(jsonb_build_object('figureId','c0bcb4b3-9a6a-4f02-aae5-2d38dbc3c15a','expectedRevision',(SELECT local_hero_revision::text FROM public.historical_figures WHERE id='c0bcb4b3-9a6a-4f02-aae5-2d38dbc3c15a'::uuid),'storyIds',jsonb_build_array('a3cbabb1-6fdc-53f8-9e03-f250108252f5')));
    IF outcome->>'ok'<>'true' THEN RAISE EXCEPTION 'LOCAL_SUBMIT_FAILED: %',outcome->'error'->>'code'; END IF;
    PERFORM set_config('request.jwt.claim.sub','a7070000-0000-4000-8000-000000000002',true);
    outcome:=public.local_hero_review_graph(jsonb_build_object('figureId','c0bcb4b3-9a6a-4f02-aae5-2d38dbc3c15a','expectedRevision',(SELECT local_hero_revision::text FROM public.historical_figures WHERE id='c0bcb4b3-9a6a-4f02-aae5-2d38dbc3c15a'::uuid),'action','publish'));
    IF outcome->>'ok'<>'true' THEN RAISE EXCEPTION 'LOCAL_PROMOTION_FAILED: %',outcome->'error'->>'code'; END IF;
  PERFORM set_config('request.jwt.claim.sub','a7070000-0000-4000-8000-000000000001',true);
    outcome:=public.local_hero_submit_graph(jsonb_build_object('figureId','82f103c8-28e6-5d62-80d7-cfe9f954ffa8','expectedRevision',(SELECT local_hero_revision::text FROM public.historical_figures WHERE id='82f103c8-28e6-5d62-80d7-cfe9f954ffa8'::uuid),'storyIds',jsonb_build_array('4448dff1-64ed-5648-980b-9d62984a8f54')));
    IF outcome->>'ok'<>'true' THEN RAISE EXCEPTION 'LOCAL_SUBMIT_FAILED: %',outcome->'error'->>'code'; END IF;
    PERFORM set_config('request.jwt.claim.sub','a7070000-0000-4000-8000-000000000002',true);
    outcome:=public.local_hero_review_graph(jsonb_build_object('figureId','82f103c8-28e6-5d62-80d7-cfe9f954ffa8','expectedRevision',(SELECT local_hero_revision::text FROM public.historical_figures WHERE id='82f103c8-28e6-5d62-80d7-cfe9f954ffa8'::uuid),'action','publish'));
    IF outcome->>'ok'<>'true' THEN RAISE EXCEPTION 'LOCAL_PROMOTION_FAILED: %',outcome->'error'->>'code'; END IF;
END $lh_promote$;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
SET LOCAL ROLE anon;
DO $lh_public$ DECLARE page jsonb; BEGIN
  page:=public.local_hero_page(NULL,'',1);
  IF (page->>'totalPeople')::integer<>2 OR (page->'coverage'->>'representedLocalities')::integer<>2 THEN RAISE EXCEPTION 'LOCAL_PUBLIC_GRAPH_MISMATCH'; END IF;
  IF page::text LIKE '%PRIVATE_%' THEN RAISE EXCEPTION 'PRIVATE_DATA_EXPOSED'; END IF;
END $lh_public$;
SELECT jsonb_build_object('localPublicPeople',public.local_hero_page(NULL,'',1)->'totalPeople','localCoverage',public.local_hero_page(NULL,'',1)->'coverage','nationalReleaseReady',false);
RESET ROLE;
ROLLBACK;
